import { Button } from "@/registry/erbium/ui/button";
import {
  Sheet,
  SheetPanel,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/registry/erbium/ui/sheet";

const SheetNoCloseButton = () => (
  <Sheet>
    <SheetTrigger render={<Button variant="outline" />}>Open Sheet</SheetTrigger>
    <SheetPanel showCloseButton={false}>
      <SheetHeader>
        <SheetTitle>No Close Button</SheetTitle>
        <SheetDescription>
          This sheet doesn&apos;t have a close button in the top-right corner. Click outside to
          close.
        </SheetDescription>
      </SheetHeader>
      <SheetContent>Review your changes here.</SheetContent>
    </SheetPanel>
  </Sheet>
);

export default SheetNoCloseButton;

import SheetNoCloseButton from "../examples/sheet-no-close-button";

const Example = () => <SheetNoCloseButton />;

export default Example;
